/**
 * A lesson's teacher-facing summary, written once in the `summary:` line of
 * its content file (content/lessons/school/<band>/<lesson>.md).
 *
 *   <LessonSummary lesson="grade-3-5/lesson-1" />
 *
 * The data module is generated by scripts/build-content.js (gitignored).
 */
import React from 'react';
import lessonSummaries from './lessonSummaries';

export default function LessonSummary({lesson}: {lesson: string}): React.ReactElement {
  const data = lessonSummaries[lesson];
  if (!data?.summary) {
    // Show the problem in development; the build warns about a missing summary too
    return <>{process.env.NODE_ENV === 'development' ? `[no summary for ${lesson}]` : ''}</>;
  }
  return <>{data.summary}</>;
}
